from pysat.solvers import Glucose3
from itertools import combinations

n = 21
edges = []
edge_idx = {}
for i in range(n):
    for j in range(i+1, n):
        edge_idx[(i,j)] = len(edges)
        edges.append((i,j))

# Variables: edge (i,j) gets variable index+1
# 0 = red, 1 = blue
# Variable v means edge is blue (1)

solver = Glucose3()

# No monochromatic red K4: not all 6 edges of any 4-clique are red (0)
# "not all red" = at least one edge is blue = OR of variables
for clique in combinations(range(n), 4):
    clause = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = clique[i], clique[j]
            if u > v:
                u, v = v, u
            clause.append(edge_idx[(u,v)] + 1)  # at least one is blue
    solver.add_clause(clause)

# No monochromatic blue K5: not all 10 edges of any 5-clique are blue (1)
# "not all blue" = at least one edge is red = OR of negations
for clique in combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            u, v = clique[i], clique[j]
            if u > v:
                u, v = v, u
            clause.append(-(edge_idx[(u,v)] + 1))  # at least one is red
    solver.add_clause(clause)

print("Solving...")
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    coloring = [0] * len(edges)
    for lit in model:
        if lit > 0:
            coloring[lit - 1] = 1
    print(f"Solution found! First 20 colors: {coloring[:20]}")
    print(f"Red edges: {coloring.count(0)}, Blue edges: {coloring.count(1)}")

# Verify the solution
def verify(coloring, n, edge_idx):
    # Check no red K4
    for clique in combinations(range(n), 4):
        all_red = True
        for i in range(4):
            for j in range(i+1, 4):
                u, v = clique[i], clique[j]
                if u > v: u, v = v, u
                if coloring[edge_idx[(u,v)]] != 0:
                    all_red = False
                    break
            if not all_red:
                break
        if all_red:
            print(f"VIOLATION: Red K4 found at {clique}")
            return False

    # Check no blue K5
    for clique in combinations(range(n), 5):
        all_blue = True
        for i in range(5):
            for j in range(i+1, 5):
                u, v = clique[i], clique[j]
                if u > v: u, v = v, u
                if coloring[edge_idx[(u,v)]] != 1:
                    all_blue = False
                    break
            if not all_blue:
                break
        if all_blue:
            print(f"VIOLATION: Blue K5 found at {clique}")
            return False

    print("Verification PASSED: No red K4, no blue K5")
    return True

verify(coloring, n, edge_idx)
print("\nFull coloring:")
print(coloring)

