for i in range(n):
    for j in range(i+1, n):
        edge_idx[(i,j)] = len(edges)
        edges.append((i,j))

solver = Glucose3()

# No monochromatic red K4: at least one edge in every 4-clique is blue
for clique in combinations(range(n), 4):
    clause = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = clique[i], clique[j]
            if u > v: u, v = v, u
            clause.append(edge_idx[(u,v)] + 1)
    solver.add_clause(clause)

# No monochromatic blue K5: at least one edge in every 5-clique is red
for clique in combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            u, v = clique[i], clique[j]
            if u > v: u, v = v, u
            clause.append(-(edge_idx[(u,v)] + 1))
    solver.add_clause(clause)

result = solver.solve()
print(f"Satisfiable: {result}")

model = solver.get_model()
coloring = [0] * len(edges)
for lit in model:
    if lit > 0 and lit <= len(edges):
        coloring[lit - 1] = 1

# Verify
def verify(coloring, n, edge_idx):
    for clique in combinations(range(n), 4):
        all_red = all(coloring[edge_idx[(min(clique[i],clique[j]), max(clique[i],clique[j]))]] == 0
                      for i in range(4) for j in range(i+1,4))
        if all_red:
            print(f"VIOLATION: Red K4 at {clique}")
            return False
    for clique in combinations(range(n), 5):
