                       for i in range(5) for j in range(i+1,5))
        if all_blue:
            print(f"VIOLATION: Blue K5 at {clique}")
            return False
    print("Verification PASSED!")
    return True

verify(coloring, n, edge_idx)
print(f"Red: {coloring.count(0)}, Blue: {coloring.count(1)}")
